AgentBoundControlCapabilitySchema::Input_kindEnum AgentBoundControlCapabilitySchema::toInput_kindEnum(const utility::string_t& value) const
{
    
    if (value == utility::conversions::to_string_t("velocity")) {
        return Input_kindEnum::VELOCITY;
    }
    
    if (value == utility::conversions::to_string_t("joints")) {
        return Input_kindEnum::JOINTS;
    }
    
    if (value == utility::conversions::to_string_t("goal")) {
        return Input_kindEnum::GOAL;
    }
    
    if (value == utility::conversions::to_string_t("pose")) {
        return Input_kindEnum::POSE;
    }
    
    if (value == utility::conversions::to_string_t("commands")) {
        return Input_kindEnum::COMMANDS;
    }
    
    throw std::invalid_argument("Invalid value for conversion to Input_kindEnum");
}


const utility::string_t AgentBoundControlCapabilitySchema::fromInput_kindEnum(const Input_kindEnum value) const
{
    switch(value)
    {
        
        case Input_kindEnum::VELOCITY: return utility::conversions::to_string_t("velocity");
        
        case Input_kindEnum::JOINTS: return utility::conversions::to_string_t("joints");
        
        case Input_kindEnum::GOAL: return utility::conversions::to_string_t("goal");
        
        case Input_kindEnum::POSE: return utility::conversions::to_string_t("pose");
        
        case Input_kindEnum::COMMANDS: return utility::conversions::to_string_t("commands");
        
    }
}


